function describe(node, depth=0) {
  if (depth > 4) return null;
  const o = { id: node.id, type: node.type, name: node.name, w: Math.round(node.width), h: Math.round(node.height) };
  if (node.type === 'TEXT') o.characters = node.characters;
  if ('fills' in node && Array.isArray(node.fills) && node.fills.length) {
    o.fills = node.fills.map(f => ({ type: f.type, color: f.color, scaleMode: f.scaleMode }));
  }
  if ('cornerRadius' in node) o.radius = node.cornerRadius;
  if ('children' in node && node.children) o.children = node.children.map(c => describe(c, depth+1));
  return o;
}
